const b = $input.first().json.body || {};
if (!/^[0-9a-f-]{36}$/i.test(b.content_id || '')) throw new Error('VALIDATION: content_id must be a UUID');
if (!['youtube', 'instagram', 'facebook'].includes(b.platform)) throw new Error('VALIDATION: unsupported platform');
const t = new Date(b.scheduled_at); if (isNaN(t)) throw new Error('VALIDATION: scheduled_at must be ISO-8601 with offset, e.g. 2026-10-02T20:00:00+05:30');
return [{ json: { content_id: b.content_id, platform: b.platform, scheduled_at: t.toISOString() } }];

const b = $input.first().json.body || {};
if (!/^[0-9a-f-]{36}$/i.test(b.publication_id || '')) throw new Error('VALIDATION: publication_id must be a UUID');
if (!['published', 'not_published'].includes(b.outcome)) throw new Error('VALIDATION: outcome must be published|not_published');
if (!String(b.reason || '').trim()) throw new Error('VALIDATION: reason is required (what did you check on the platform?)');
if (b.outcome === 'published' && !String(b.post_id || '').trim()) throw new Error('VALIDATION: post_id is required to confirm a publication');
return [{ json: { publication_id: b.publication_id, outcome: b.outcome, post_id: b.post_id ? String(b.post_id).slice(0, 200) : null, reason: String(b.reason).slice(0, 500), by: String(b.by || 'owner').slice(0, 80) } }];

// Maps a database/validation outcome to an HTTP status + structured JSON. No stack traces / internals are ever returned.
const clean = m => String(m || '').replace(/^"+|"+$/g, '').replace(/^(?:Error: )?(?:VALIDATION: )?/, '').replace(/ \[line \d+\]$/, '').slice(0, 300);
const e = $input.first().json; return [{ json: { status: 400, body: { ok: false, error: 'VALIDATION', message: clean(e.error?.message ?? e.error ?? e.message) } } }];

